            diff_right = abs(nums[i] - nums[i + 1])
            if diff_right < diff_left:
                is_closest = True
        cost = 1 if is_closest else abs(nums[i + 1] - nums[i])
        pref_fwd[i + 1] = pref_fwd[i] + cost

    pref_bwd = [0] * n
