#include <vector>
#include <cmath>

class Solution {
public:
    std::vector<int> minCostToMove(std::vector<int>& nums, std::vector<std::vector<int>>& queries) {
        int n = nums.size();
        std::vector<int> prefFwd(n, 0);
        for (int i = 0; i < n - 1; ++i) {
            bool isClosest = false;
            if (i == 0) {
                isClosest = true;
            } else {
                int diffLeft = std::abs(nums[i] - nums[i - 1]);
                int diffRight = std::abs(nums[i] - nums[i + 1]);
                if (diffRight < diffLeft) isClosest = true;
            }
            int cost = isClosest ? 1 : std::abs(nums[i + 1] - nums[i]);
            prefFwd[i + 1] = prefFwd[i] + cost;
        }
        std::vector<int> prefBwd(n, 0);
        for (int i = n - 1; i > 0; --i) {
            bool isClosest = false;
            if (i == n - 1) {
                isClosest = true;
            } else {
                int diffLeft = std::abs(nums[i] - nums[i - 1]);
                int diffRight = std::abs(nums[i] - nums[i + 1]);
                if (diffLeft <= diffRight) isClosest = true;
            }
            int cost = isClosest ? 1 : std::abs(nums[i] - nums[i - 1]);
            prefBwd[i - 1] = prefBwd[i] + cost;
        }
        std::vector<int> ans;
        for (const auto& q : queries) {
            int l = q[0], r = q[1];
            if (l == r) ans.push_back(0);
            else if (l < r) ans.push_back(prefFwd[r] - prefFwd[l]);
            else ans.push_back(prefBwd[r] - prefBwd[l]);
        }
        return ans;
    }
};

