function minCostToMove(nums, queries) {
    const n = nums.length;
    const prefFwd = new Array(n).fill(0);
    for (let i = 0; i < n - 1; i++) {
        let isClosest = false;
        if (i === 0) {
            isClosest = true;
        } else {
            const diffLeft = Math.abs(nums[i] - nums[i - 1]);
            const diffRight = Math.abs(nums[i] - nums[i + 1]);
            if (diffRight < diffLeft) isClosest = true;
        }
        const cost = isClosest ? 1 : Math.abs(nums[i + 1] - nums[i]);
        prefFwd[i + 1] = prefFwd[i] + cost;
    }
    const prefBwd = new Array(n).fill(0);
    for (let i = n - 1; i > 0; i--) {
        let isClosest = false;
        if (i === n - 1) {
            isClosest = true;
        } else {
            const diffLeft = Math.abs(nums[i] - nums[i - 1]);
            const diffRight = Math.abs(nums[i] - nums[i + 1]);
            if (diffLeft <= diffRight) isClosest = true;
        }
        const cost = isClosest ? 1 : Math.abs(nums[i] - nums[i - 1]);
        prefBwd[i - 1] = prefBwd[i] + cost;
    }
    const ans = [];
    for (const [l, r] of queries) {
